-- ============================================================
-- CUSTOMER & REVENUE INTELLIGENCE PLATFORM
-- CUSTOMER ANALYSIS
-- ============================================================

-- ------------------------------------------------------------
-- 1. UNIQUE CUSTOMERS
-- Business Question:
-- How many individual customers placed delivered orders?
--
-- customer_unique_id is used rather than customer_id because
-- the same individual can have different customer_id values
-- across separate orders.
-- ------------------------------------------------------------

SELECT
    COUNT(DISTINCT c.customer_unique_id)
        AS unique_customers

FROM orders AS o

INNER JOIN customers AS c
    ON o.customer_id = c.customer_id

WHERE o.order_status = 'delivered';

93358

-- ------------------------------------------------------------
-- 2. PURCHASE FREQUENCY BY CUSTOMER
-- Business Question:
-- How many delivered orders has each customer placed?
-- ------------------------------------------------------------

SELECT
    c.customer_unique_id,

    COUNT(DISTINCT o.order_id)
        AS number_of_orders

FROM orders AS o

INNER JOIN customers AS c
    ON o.customer_id = c.customer_id

WHERE o.order_status = 'delivered'

GROUP BY c.customer_unique_id

ORDER BY number_of_orders DESC;

