-- ------------------------------------------------------------
-- 3. ONE-TIME VS REPEAT CUSTOMERS
-- Business Question:
-- How many customers purchased once versus multiple times?
-- ------------------------------------------------------------

WITH customer_orders AS (

    SELECT
        c.customer_unique_id,

        COUNT(DISTINCT o.order_id)
            AS number_of_orders

    FROM orders AS o

    INNER JOIN customers AS c
        ON o.customer_id = c.customer_id

    WHERE o.order_status = 'delivered'

    GROUP BY c.customer_unique_id
)

SELECT

    CASE
        WHEN number_of_orders = 1
            THEN 'One-time customer'
        ELSE 'Repeat customer'
    END AS customer_type,

    COUNT(*) AS customers,

    ROUND(
        COUNT(*) * 100.0
        /
        SUM(COUNT(*)) OVER (),
        2
    ) AS percentage_of_customers

FROM customer_orders

GROUP BY
    CASE
        WHEN number_of_orders = 1
            THEN 'One-time customer'
        ELSE 'Repeat customer'
    END

ORDER BY customers DESC;

"One-time customer"	90557	97.00
"Repeat customer"	2801	3.00

-- ------------------------------------------------------------
-- 4. REPEAT PURCHASE RATE
-- Business Question:
-- What percentage of customers placed more than one
-- delivered order?
-- ------------------------------------------------------------

WITH customer_orders AS (

    SELECT
        c.customer_unique_id,

        COUNT(DISTINCT o.order_id)
            AS number_of_orders

    FROM orders AS o

    INNER JOIN customers AS c
        ON o.customer_id = c.customer_id

    WHERE o.order_status = 'delivered'

    GROUP BY c.customer_unique_id
)

SELECT

    COUNT(*) AS total_customers,

    COUNT(*) FILTER (
        WHERE number_of_orders > 1
    ) AS repeat_customers,

    ROUND(
        (
            COUNT(*) FILTER (
                WHERE number_of_orders > 1
            )
            * 100.0
            / COUNT(*)
        ),
        2
    ) AS repeat_purchase_rate_pct

FROM customer_orders;

93358	2801	3.00

-- ------------------------------------------------------------
-- 5. REVENUE BY CUSTOMER TYPE
-- Business Question:
-- How much product revenue is generated by one-time versus
-- repeat customers?
-- ------------------------------------------------------------

WITH customer_metrics AS (

    SELECT
        c.customer_unique_id,

        COUNT(DISTINCT o.order_id)
            AS number_of_orders,

        SUM(oi.price)
            AS customer_revenue

    FROM orders AS o

    INNER JOIN customers AS c
        ON o.customer_id = c.customer_id

    INNER JOIN order_items AS oi
        ON o.order_id = oi.order_id

    WHERE o.order_status = 'delivered'

    GROUP BY c.customer_unique_id
),

customer_segments AS (

    SELECT
        customer_unique_id,
        customer_revenue,

        CASE
            WHEN number_of_orders = 1
                THEN 'One-time customer'
            ELSE 'Repeat customer'
        END AS customer_type

    FROM customer_metrics
)

SELECT
    customer_type,

    COUNT(*) AS customers,

    ROUND(
        SUM(customer_revenue)::numeric,
        2
    ) AS product_revenue,

    ROUND(
        (
            SUM(customer_revenue)
            /
            SUM(SUM(customer_revenue)) OVER ()
            * 100
        )::numeric,
        2
    ) AS revenue_share_pct

FROM customer_segments

GROUP BY customer_type

ORDER BY product_revenue DESC;

