-- ------------------------------------------------------------
-- 7. TOP 10% CUSTOMER REVENUE CONCENTRATION
-- Business Question:
-- What percentage of product revenue is generated by the
-- highest-value 10% of customers?
-- ------------------------------------------------------------

WITH customer_revenue AS (

    SELECT
        c.customer_unique_id,
        SUM(oi.price) AS revenue

    FROM customers AS c

    INNER JOIN orders AS o
        ON c.customer_id = o.customer_id

    INNER JOIN order_items AS oi
        ON o.order_id = oi.order_id

    WHERE o.order_status = 'delivered'

    GROUP BY c.customer_unique_id
),

ranked_customers AS (

    SELECT
        customer_unique_id,
        revenue,

        NTILE(10) OVER (
            ORDER BY revenue DESC
        ) AS revenue_decile

    FROM customer_revenue
)

SELECT

    ROUND(
        SUM(revenue) FILTER (
            WHERE revenue_decile = 1
        )::numeric,
        2
    ) AS top_10_percent_revenue,

    ROUND(
        SUM(revenue)::numeric,
        2
    ) AS total_revenue,

    ROUND(
        (
            SUM(revenue) FILTER (
                WHERE revenue_decile = 1
            )
            /
            SUM(revenue)
            * 100
        )::numeric,
        2
    ) AS top_10_percent_revenue_share

FROM ranked_customers;

