-- ------------------------------------------------------------
-- 9. TIME BETWEEN REPEAT PURCHASES
-- Business Question:
-- How long does it take repeat customers to place another
-- delivered order?
-- ------------------------------------------------------------

WITH customer_orders AS (

    SELECT
        c.customer_unique_id,
        o.order_id,
        o.order_purchase_timestamp::timestamp
            AS purchase_date,

        LAG(
            o.order_purchase_timestamp::timestamp
        ) OVER (
            PARTITION BY c.customer_unique_id
            ORDER BY o.order_purchase_timestamp::timestamp
        ) AS previous_purchase_date

    FROM customers AS c

    INNER JOIN orders AS o
        ON c.customer_id = o.customer_id

    WHERE o.order_status = 'delivered'
),

repeat_intervals AS (

    SELECT
        customer_unique_id,
        purchase_date,
        previous_purchase_date,

        EXTRACT(
            EPOCH FROM (
                purchase_date - previous_purchase_date
            )
        ) / 86400 AS days_between_purchases

    FROM customer_orders

    WHERE previous_purchase_date IS NOT NULL
)

SELECT

    COUNT(*) AS repeat_purchase_intervals,

    ROUND(
        AVG(days_between_purchases)::numeric,
        2
    ) AS average_days_between_purchases,

    ROUND(
        PERCENTILE_CONT(0.5)
        WITHIN GROUP (
            ORDER BY days_between_purchases
        )::numeric,
        2
    ) AS median_days_between_purchases

FROM repeat_intervals;

"repeat_purchase_intervals"	"average_days_between_purchases"	"median_days_between_purchases"
