-- 10. RFM ANALYSIS REFERENCE DATE
-- Purpose:
-- Establish a reference date immediately after the latest
-- purchase in the historical dataset.
-- ------------------------------------------------------------

SELECT
    MAX(order_purchase_timestamp::timestamp)
        AS latest_purchase,

    MAX(order_purchase_timestamp::timestamp)
        + INTERVAL '1 day'
        AS rfm_reference_date

FROM orders

WHERE order_status = 'delivered';

