-- ------------------------------------------------------------
-- 11. RAW RFM CUSTOMER METRICS
-- Business Question:
-- What are each customer's Recency, Frequency, and Monetary
-- values at the end of the observation period?
-- ------------------------------------------------------------

WITH reference_date AS (

    SELECT
        MAX(order_purchase_timestamp::timestamp)
            + INTERVAL '1 day' AS analysis_date

    FROM orders

    WHERE order_status = 'delivered'
)

SELECT
    c.customer_unique_id,

    (
        SELECT analysis_date
        FROM reference_date
    )::date
    -
    MAX(
        o.order_purchase_timestamp::timestamp
    )::date
        AS recency_days,

    COUNT(DISTINCT o.order_id)
        AS frequency,

    ROUND(
        SUM(oi.price)::numeric,
        2
    ) AS monetary_value

FROM customers AS c

INNER JOIN orders AS o
    ON c.customer_id = o.customer_id

INNER JOIN order_items AS oi
    ON o.order_id = oi.order_id

WHERE o.order_status = 'delivered'

GROUP BY c.customer_unique_id

ORDER BY monetary_value DESC;

-- ------------------------------------------------------------
-- 12. RFM RECENCY DISTRIBUTION
-- Purpose:
-- Understand customer recency before defining segmentation
-- thresholds.
-- ------------------------------------------------------------

WITH reference_date AS (

    SELECT
        MAX(order_purchase_timestamp::timestamp)
            + INTERVAL '1 day' AS analysis_date

    FROM orders

    WHERE order_status = 'delivered'
),

customer_recency AS (

    SELECT
        c.customer_unique_id,

        (
            SELECT analysis_date
            FROM reference_date
        )::date
        -
        MAX(
            o.order_purchase_timestamp::timestamp
        )::date
            AS recency_days

    FROM customers AS c

    INNER JOIN orders AS o
        ON c.customer_id = o.customer_id

    WHERE o.order_status = 'delivered'

    GROUP BY c.customer_unique_id
)

SELECT

    MIN(recency_days)
        AS minimum_recency,

    ROUND(
        PERCENTILE_CONT(0.25)
        WITHIN GROUP (ORDER BY recency_days)::numeric,
        2
    ) AS percentile_25,

    ROUND(
        PERCENTILE_CONT(0.50)
        WITHIN GROUP (ORDER BY recency_days)::numeric,
        2
    ) AS median_recency,

    ROUND(
        PERCENTILE_CONT(0.75)
        WITHIN GROUP (ORDER BY recency_days)::numeric,
        2
    ) AS percentile_75,

    MAX(recency_days)
        AS maximum_recency

FROM customer_recency;

"minimum_recency"	"percentile_25"	"median_recency"	"percentile_75"	"maximum_recency"
1	115.00	219.00	347.00	714

-- ------------------------------------------------------------
-- 13. RFM MONETARY DISTRIBUTION
-- Purpose:
-- Understand customer spending distribution before defining
-- segmentation thresholds.
-- ------------------------------------------------------------

WITH customer_monetary AS (

    SELECT
        c.customer_unique_id,
        SUM(oi.price) AS monetary_value

    FROM customers AS c

    INNER JOIN orders AS o
        ON c.customer_id = o.customer_id

    INNER JOIN order_items AS oi
        ON o.order_id = oi.order_id

    WHERE o.order_status = 'delivered'

    GROUP BY c.customer_unique_id
)

SELECT

    ROUND(MIN(monetary_value)::numeric, 2)
        AS minimum_value,

    ROUND(
        PERCENTILE_CONT(0.25)
        WITHIN GROUP (ORDER BY monetary_value)::numeric,
        2
    ) AS percentile_25,

    ROUND(
        PERCENTILE_CONT(0.50)
        WITHIN GROUP (ORDER BY monetary_value)::numeric,
        2
    ) AS median_value,

    ROUND(
        PERCENTILE_CONT(0.75)
        WITHIN GROUP (ORDER BY monetary_value)::numeric,
        2
    ) AS percentile_75,

    ROUND(MAX(monetary_value)::numeric, 2)
        AS maximum_value

FROM customer_monetary;

"minimum_value"	"percentile_25"	"median_value"	"percentile_75"	"maximum_value"
0.85	47.65	89.73	154.74	13440.00

-- ------------------------------------------------------------
-- 14. RFM CUSTOMER SCORING
-- Business Question:
-- How can customers be scored based on Recency, Frequency,
-- and Monetary value?
--
-- Methodology:
-- Recency and Monetary scores use dataset quartiles.
-- Frequency uses behavioral purchase-count bands because
-- 97% of customers have only one delivered order.
-- ------------------------------------------------------------

WITH reference_date AS (

    SELECT
        MAX(order_purchase_timestamp::timestamp)
            + INTERVAL '1 day' AS analysis_date
    FROM orders
    WHERE order_status = 'delivered'
),

rfm_base AS (

    SELECT
        c.customer_unique_id,

        (
            SELECT analysis_date
            FROM reference_date
        )::date
        -
        MAX(o.order_purchase_timestamp::timestamp)::date
            AS recency_days,

        COUNT(DISTINCT o.order_id)
            AS frequency,

        SUM(oi.price)
            AS monetary_value

    FROM customers AS c

    INNER JOIN orders AS o
        ON c.customer_id = o.customer_id

    INNER JOIN order_items AS oi
        ON o.order_id = oi.order_id

    WHERE o.order_status = 'delivered'

    GROUP BY c.customer_unique_id
),

rfm_scores AS (

    SELECT
        customer_unique_id,
        recency_days,
        frequency,
        monetary_value,

        CASE
            WHEN recency_days <= 115 THEN 4
            WHEN recency_days <= 219 THEN 3
            WHEN recency_days <= 347 THEN 2
            ELSE 1
        END AS recency_score,

        CASE
            WHEN frequency = 1 THEN 1
            WHEN frequency = 2 THEN 2
            WHEN frequency = 3 THEN 3
            ELSE 4
        END AS frequency_score,

        CASE
            WHEN monetary_value <= 47.65 THEN 1
            WHEN monetary_value <= 89.73 THEN 2
            WHEN monetary_value <= 154.74 THEN 3
            ELSE 4
        END AS monetary_score

    FROM rfm_base
)

SELECT
    customer_unique_id,
    recency_days,
    frequency,

    ROUND(
        monetary_value::numeric,
        2
    ) AS monetary_value,

    recency_score,
    frequency_score,
    monetary_score,

    CONCAT(
        recency_score,
        frequency_score,
        monetary_score
    ) AS rfm_code,

    recency_score
        + frequency_score
        + monetary_score AS rfm_total_score

FROM rfm_scores

ORDER BY rfm_total_score DESC,
         monetary_value DESC;


-- ------------------------------------------------------------
-- 15. RFM CUSTOMER SEGMENTATION
-- Business Question:
-- Which actionable customer segments exist based on RFM
-- behavior?
-- ------------------------------------------------------------

WITH reference_date AS (

    SELECT
        MAX(order_purchase_timestamp::timestamp)
            + INTERVAL '1 day' AS analysis_date
    FROM orders
    WHERE order_status = 'delivered'
),

rfm_base AS (

    SELECT
        c.customer_unique_id,

        (
            SELECT analysis_date
            FROM reference_date
        )::date
        -
        MAX(o.order_purchase_timestamp::timestamp)::date
            AS recency_days,

        COUNT(DISTINCT o.order_id)
            AS frequency,

        SUM(oi.price)
            AS monetary_value

    FROM customers AS c

    INNER JOIN orders AS o
        ON c.customer_id = o.customer_id

    INNER JOIN order_items AS oi
        ON o.order_id = oi.order_id

    WHERE o.order_status = 'delivered'

    GROUP BY c.customer_unique_id
),

rfm_scores AS (

    SELECT
        *,

        CASE
            WHEN recency_days <= 115 THEN 4
            WHEN recency_days <= 219 THEN 3
            WHEN recency_days <= 347 THEN 2
            ELSE 1
        END AS r_score,

        CASE
            WHEN frequency = 1 THEN 1
            WHEN frequency = 2 THEN 2
            WHEN frequency = 3 THEN 3
            ELSE 4
        END AS f_score,

        CASE
            WHEN monetary_value <= 47.65 THEN 1
            WHEN monetary_value <= 89.73 THEN 2
            WHEN monetary_value <= 154.74 THEN 3
            ELSE 4
        END AS m_score

    FROM rfm_base
),

customer_segments AS (

    SELECT
        *,

        CASE

            -- Recent repeat customers with strong spending
            WHEN r_score >= 3
                 AND f_score >= 2
                 AND m_score >= 3
                THEN 'Champions'

            -- Repeat customers who remain relatively recent
            WHEN r_score >= 3
                 AND f_score >= 2
                THEN 'Loyal Customers'

            -- Very recent, high-spending one-time customers
            WHEN r_score = 4
                 AND f_score = 1
                 AND m_score = 4
                THEN 'High-Value Recent'

            -- Recent one-time customers with conversion potential
            WHEN r_score >= 3
                 AND f_score = 1
                THEN 'Potential Loyalists'

            -- Previously valuable/repeat customers who are no longer recent
            WHEN r_score <= 2
                 AND (
                     f_score >= 2
                     OR m_score >= 3
                 )
                THEN 'At Risk'

            ELSE 'Low Engagement'

        END AS customer_segment

    FROM rfm_scores
)

SELECT
    customer_unique_id,
    recency_days,
    frequency,

    ROUND(
        monetary_value::numeric,
        2
    ) AS monetary_value,

    r_score,
    f_score,
    m_score,

    customer_segment

FROM customer_segments

ORDER BY monetary_value DESC;

-- ------------------------------------------------------------
-- 16. RFM SEGMENT SUMMARY — FINAL MODEL
-- Business Question:
-- How large and valuable is each customer segment?
--
-- Methodology:
-- Because 97% of customers have only one delivered order,
-- segmentation explicitly distinguishes one-time customers
-- from customers demonstrating repeat purchase behavior.
-- ------------------------------------------------------------

WITH reference_date AS (

    SELECT
        MAX(order_purchase_timestamp::timestamp)
            + INTERVAL '1 day' AS analysis_date
    FROM orders
    WHERE order_status = 'delivered'
),

rfm_base AS (

    SELECT
        c.customer_unique_id,

        (
            SELECT analysis_date
            FROM reference_date
        )::date
        -
        MAX(o.order_purchase_timestamp::timestamp)::date
            AS recency_days,

        COUNT(DISTINCT o.order_id)
            AS frequency,

        SUM(oi.price)
            AS monetary_value

    FROM customers AS c

    INNER JOIN orders AS o
        ON c.customer_id = o.customer_id

    INNER JOIN order_items AS oi
        ON o.order_id = oi.order_id

    WHERE o.order_status = 'delivered'

    GROUP BY c.customer_unique_id
),

rfm_scores AS (

    SELECT
        *,

        CASE
            WHEN recency_days <= 115 THEN 4
            WHEN recency_days <= 219 THEN 3
            WHEN recency_days <= 347 THEN 2
            ELSE 1
        END AS r_score,

        CASE
            WHEN frequency = 1 THEN 1
            WHEN frequency = 2 THEN 2
            WHEN frequency = 3 THEN 3
            ELSE 4
        END AS f_score,

        CASE
            WHEN monetary_value <= 47.65 THEN 1
            WHEN monetary_value <= 89.73 THEN 2
            WHEN monetary_value <= 154.74 THEN 3
            ELSE 4
        END AS m_score

    FROM rfm_base
),

customer_segments AS (

    SELECT
        *,

        CASE

            -- Recent repeat customers with above-median value
            WHEN r_score >= 3
                 AND frequency >= 2
                 AND m_score >= 3
                THEN 'Champions'

            -- Other recent customers demonstrating repeat behavior
            WHEN r_score >= 3
                 AND frequency >= 2
                THEN 'Active Repeat'

            -- Most recent quartile + highest monetary quartile
            -- but no repeat purchase yet
            WHEN r_score = 4
                 AND frequency = 1
                 AND m_score = 4
                THEN 'High-Value Recent'

            -- Other relatively recent one-time customers
            WHEN r_score >= 3
                 AND frequency = 1
                THEN 'Recent One-Time'

            -- Older customers with either repeat history
            -- or above-median monetary value
            WHEN r_score <= 2
                 AND (
                     frequency >= 2
                     OR m_score >= 3
                 )
                THEN 'At-Risk Valuable'

            -- Older low-value one-time customers
            ELSE 'Inactive Low-Value'

        END AS customer_segment

    FROM rfm_scores
)

SELECT
    customer_segment,

    COUNT(*) AS customers,

    ROUND(
        (
            COUNT(*) * 100.0
            / SUM(COUNT(*)) OVER ()
        )::numeric,
        2
    ) AS customer_share_pct,

    ROUND(
        SUM(monetary_value)::numeric,
        2
    ) AS product_revenue,

    ROUND(
        (
            SUM(monetary_value)
            * 100.0
            / SUM(SUM(monetary_value)) OVER ()
        )::numeric,
        2
    ) AS revenue_share_pct,

    ROUND(
        AVG(monetary_value)::numeric,
        2
    ) AS average_customer_value,

    ROUND(
        AVG(recency_days)::numeric,
        2
    ) AS average_recency_days,

    ROUND(
        AVG(frequency)::numeric,
        2
    ) AS average_frequency

FROM customer_segments

GROUP BY customer_segment

ORDER BY product_revenue DESC;

